// Run after `yarn build`: node --test tests/npc-dialogues-counted-random.test.cjs
// A "counted" random ({type: 'random', count: N, non_repeating: true}) plays N alternatives drawn without replacement,
// with the wiki's '[first/second/third and final]' filled in by the draw, the 'After the <ordinal> question is answered:'
// sibling blocks between the draws and the third block's own conditions after the last one.
//
// PROSPECTIVE-CONTRACT FIXTURE: the shape below is a trimmed copy of the Curpile Fyod subtree generated by
// osrsreboxed-db PR 108 (RSPSApp/osrsreboxed-db, commit f860dc1cdd2341f70f632bc211c8680a90a17503, shard
// docs/dialogues/df21aef518b8a716.json, sha256 09fabadba289ed9cb570dae292fb9e44ef856f0f01a00322a2e00141942e698a,
// variant convincing-curpile-fyod-talking-to-curpile-fyod): three alternatives instead of six, a two-option menu per
// question and one count condition set. No current data carries `count`; this test is NOT evidence that the live record
// plays correctly, and nothing is copied into npc-dialogues.json.
const assert = require('node:assert/strict');
const { test } = require('node:test');
const { Server } = require('../dist/Server');
Server.installProductionPathResolver();
const { PluginManager } = require('../dist/plugins/PluginManager');
const { startDialogue } = require('../plugins/npcs/NpcDialogues.plugin');

const question = (id, text, right, wrong) => ({
  text: `Dialogue ${id}`,
  steps: [
    { type: 'line', speaker: 'Curpile Fyod', text: `Okay, [first/second/third and final] question. ${text}` },
    { type: 'choice', options: [
      { text: right, steps: [{ player: right }, { type: 'jump', reference: 'continue', id: `right${id}` }] },
      { text: wrong, steps: [{ player: wrong }, { type: 'jump', reference: 'continue', id: `wrong${id}` }] },
    ] },
  ],
});
const tree = () => [
  { type: 'line', speaker: 'Curpile Fyod', text: "Hey... Don't tempt me!" },
  { type: 'random', count: 3, non_repeating: true, options: [
    question(1, 'Q1?', 'A1', 'B1'), question(2, 'Q2?', 'A2', 'B2'), question(3, 'Q3?', 'A3', 'B3'),
  ] },
  { type: 'condition', text: 'After the first question is answered:', id: 'after1', steps: [
    { type: 'line', speaker: 'Curpile Fyod', text: "That's the first question done." }, { type: 'action', text: '(Continues above)', id: 'cont1' }] },
  { type: 'condition', text: 'After the second question is answered:', id: 'after2', steps: [
    { type: 'line', speaker: 'Curpile Fyod', text: "That's the second question answered." }, { type: 'action', text: '(Continues above)', id: 'cont2' }] },
  { type: 'condition', text: 'After the third question is answered:', id: 'after3', steps: [
    { type: 'line', speaker: 'Curpile Fyod', text: "That's the third question answered." },
    { type: 'condition', text: 'If the player answered zero out of three questions correctly:', id: 'zero', steps: [
      { type: 'line', speaker: 'Curpile Fyod', text: 'You got no questions correct!' }, { type: 'message', text: 'Curpile knocks you out.', id: 'knock0' }, { type: 'end' }] },
    { type: 'condition', text: 'If the player answered three out of three questions correctly:', id: 'three', steps: [
      { type: 'line', speaker: 'Curpile Fyod', text: 'I believes ya. Go on in.' }] },
  ] },
];

function play(t, answers, { random = () => 0, conditions = () => null, steps = tree() } = {}) {
  const said = [], acted = [], events = [], prompts = [];
  const player = {
    getDialogueManager: () => ({
      reset() {},
      startDialogues(chain) {
        for (const entry of [...chain.getDialogues().values()].sort((a, b) => a.getIndex() - b.getIndex())) {
          if (entry.text) said.push(String(entry.text));
          try { entry.send(player); } catch { /* unwired dialogue entries are fine here */ }
        }
      },
    }),
    getPacketSender: () => ({ sendInterfaceRemoval() {} }),
    sendMessage() {},
  };
  const api = {
    emitCustomEvent(name, payload) {
      events.push([name, payload]);
      if (name === 'npc-dialogue:action' && payload.stepId) { acted.push(payload.stepId); payload.handled = true; }
    },
    sendMultiChatboxPrompt(_player, title, ...pairs) { prompts.push({ title, pairs }); return true; },
  };
  t.mock.method(PluginManager, 'emitNpcDialogueCondition', (event) => conditions(event));
  t.mock.method(Math, 'random', random);
  const definition = { getName: () => 'Curpile Fyod', getId: () => 5057 };
  const event = { player, npc: { getId: () => 5057 }, npcId: 5057, definition };
  startDialogue(api, event, steps, {}, { player, npc: event.npc, npcId: 5057, definition, pages: [] });
  const labels = () => prompts.at(-1)?.pairs.filter((_, i) => i % 2 === 0) ?? [];
  const choose = (label) => { const pairs = prompts.at(-1).pairs; const at = pairs.findIndex((p, i) => i % 2 === 0 && p === label); assert.ok(at >= 0, `no ${label} in ${labels()}`); pairs[at + 1](); };
  for (const label of answers) choose(label);
  return { said, acted, events, prompts, labels, choose };
}
const draws = (events) => events.filter(([name]) => name === 'npc-dialogue:draw').map(([, p]) => p);

test('a counted random draws three distinct alternatives in turn with the ordinal filled and the acknowledgements between', (t) => {
  const run = play(t, ['A1', 'A2', 'A3'], { conditions: (e) => e.stepId === 'three' });
  const questions = run.said.filter((text) => /question\. Q\d\?$/.test(text));
  assert.deepEqual(questions, ['Okay, first question. Q1?', 'Okay, second question. Q2?', 'Okay, third and final question. Q3?']);
  const lines = run.said;
  assert.ok(lines.indexOf("That's the first question done.") > lines.indexOf('Okay, first question. Q1?'));
  assert.ok(lines.indexOf('Okay, second question. Q2?') > lines.indexOf("That's the first question done."));
  assert.ok(lines.indexOf("That's the second question answered.") < lines.indexOf('Okay, third and final question. Q3?'));
  assert.ok(lines.indexOf("That's the third question answered.") > lines.indexOf('Okay, third and final question. Q3?'));
  assert.ok(lines.includes('I believes ya. Go on in.'), lines.join(' | '));
  assert.ok(!run.said.some((text) => text.includes('[first/second/third and final]')), 'no literal placeholder is spoken');
});

test('the draws are without replacement whatever the random values are', (t) => {
  for (const random of [() => 0, () => 0.99, () => 0.5]) {
    const run = play(t, [], { random });
    let seenPrompts = 0;
    while (run.prompts.length > seenPrompts && seenPrompts < 6) { seenPrompts = run.prompts.length; run.choose(run.labels()[0]); }
    const seen = draws(run.events).map((d) => d.text);
    assert.equal(seen.length, 3, `three draws: ${seen}`);
    assert.equal(new Set(seen).size, 3, `distinct: ${seen}`);
    t.mock.restoreAll();
  }
});

test('a draw event tells the plugin which question was asked, unsubstituted, and which draw it is', (t) => {
  const run = play(t, ['A1', 'B2', 'A3'], { conditions: () => null });
  const events = draws(run.events);
  assert.deepEqual(events.map((d) => [d.draw, d.count, d.text]), [[1, 3, 'Dialogue 1'], [2, 3, 'Dialogue 2'], [3, 3, 'Dialogue 3']]);
  assert.equal(events[0].question, 'Okay, [first/second/third and final] question. Q1?');
});

test('(Continues above) is the loop signal only inside the after-blocks: the marker is not played there, an ordinary action with that text elsewhere is', (t) => {
  const steps = tree();
  steps.unshift({ type: 'action', text: '(Continues above)', id: 'outside' });
  const run = play(t, ['A1', 'A2', 'A3'], { steps, conditions: (e) => e.stepId === 'three' });
  assert.deepEqual(run.acted, ['outside'], 'only the action outside an after-block is emitted');
});

test('the third block hands its count conditions to the ordinary condition handler: zero correct knocks the player out', (t) => {
  const run = play(t, ['B1', 'B2', 'B3'], { conditions: (e) => e.stepId === 'zero' });
  assert.ok(run.said.includes('You got no questions correct!'), run.said.join(' | '));
  assert.ok(run.acted.includes('knock0'));
  assert.ok(!run.said.includes('I believes ya. Go on in.'));
});

test('fewer alternatives than the count: it draws what exists and then continues', (t) => {
  const steps = tree();
  steps[1].options = steps[1].options.slice(0, 2);
  const run = play(t, ['A1', 'A2'], { steps, conditions: (e) => e.stepId === 'three' });
  assert.equal(draws(run.events).length, 2);
  assert.ok(run.said.includes("That's the second question answered.") || run.said.includes("That's the third question answered."), run.said.join(' | '));
});

test('a random without count and non_repeating plays exactly one alternative, as before', (t) => {
  const steps = [
    { type: 'random', count: 3, options: [question(1, 'Q1?', 'A1', 'B1'), question(2, 'Q2?', 'A2', 'B2')] },
  ];
  const run = play(t, [], { steps, random: () => 0.99 });
  assert.equal(draws(run.events).length, 0, 'no draw events on the plain path');
  assert.ok(run.said.some((text) => text.includes('[first/second/third and final]')), 'the literal text is untouched on the plain path');
  assert.equal(run.said.filter((text) => /question\./.test(text)).length, 1);
});
